/* Portable reference; connect real routes/data before production. */
document.addEventListener('DOMContentLoaded',()=>{const app=document.querySelector('#app'),side=document.querySelector('#sidebar'),overlay=document.querySelector('#overlay'),mobile=()=>innerWidth<=991;const close=()=>{side?.classList.remove('open');overlay?.classList.remove('show')};document.querySelector('#btnHamburger')?.addEventListener('click',()=>{side?.classList.add('open');overlay?.classList.add('show')});overlay?.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#searchInput')?.focus()}});document.querySelector('#darkToggle')?.addEventListener('change',e=>{let t=e.target.checked?'dark':'light';document.documentElement.dataset.theme=t;document.documentElement.dataset.bsTheme=t;localStorage.setItem('tc_mode',t)});document.querySelector('#btnToggle')?.addEventListener('click',()=>{if(!mobile()){app?.classList.toggle('col');localStorage.setItem('ks_col',app?.classList.contains('col')?'1':'0')}});window.addEventListener('resize',()=>{if(!mobile())close()});window.lucide?.createIcons()});
